@import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@400;500;600;700&family=Jost:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* Biophilic — deep greens and earth tones, organic blob radii, soft natural light */
.theme-biophilic {
  --bg: oklch(0.96 0.018 110);
  --surface: oklch(0.99 0.012 110);
  --surface-2: oklch(0.92 0.03 120);
  --fg: oklch(0.26 0.045 150);
  --fg-muted: oklch(0.48 0.03 140);
  --accent: oklch(0.48 0.11 150);
  --accent-fg: oklch(0.98 0.012 110);
  --accent-2: oklch(0.66 0.11 65);
  --line: oklch(0.85 0.03 125);
  --success: oklch(0.55 0.13 150);
  --warning: oklch(0.72 0.14 75);
  --danger: oklch(0.52 0.15 35);

  --radius: 1.5rem;
  --radius-sm: 0.875rem;
  --radius-lg: 2.5rem 1.25rem 2.5rem 1.25rem;
  --radius-pill: 999px;

  --shadow-1: 0 2px 10px -4px oklch(0.3 0.06 150 / 0.25);
  --shadow-2: 0 10px 30px -12px oklch(0.3 0.06 150 / 0.3);
  --shadow-3: 0 24px 60px -20px oklch(0.3 0.06 150 / 0.35);
  --glow: 0 0 0 4px oklch(0.48 0.11 150 / 0.2);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Fraunces", Georgia, serif;
  --font-body: "Jost", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.015em;
  --label-transform: none;
  --label-tracking: 0.06em;

  background-color: var(--bg);
  background-image:
    radial-gradient(60% 45% at 12% 0%, oklch(0.8 0.1 150 / 0.35), transparent 70%),
    radial-gradient(50% 40% at 92% 12%, oklch(0.85 0.09 90 / 0.35), transparent 70%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-biophilic h1,
.theme-biophilic h2,
.theme-biophilic h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-biophilic button { border-radius: 1.25rem 2rem 1.25rem 2rem; }
.theme-biophilic h1 { font-weight: 500; }
.theme-biophilic h2::before { content: "❧ "; color: var(--accent); }

/* depth */
.theme-biophilic thead th { color: var(--accent); font-family: var(--font-display); font-style: italic; font-weight: 500; font-size: 0.82em; letter-spacing: 0.04em; border-bottom: 2px solid oklch(0.48 0.11 150 / 35%); background: oklch(0.92 0.03 120 / 50%); }
.theme-biophilic td { border-bottom: 1px solid oklch(0.85 0.03 125 / 70%); }
.theme-biophilic tbody tr:hover { background: oklch(0.92 0.04 130 / 60%); }
.theme-biophilic input, .theme-biophilic textarea, .theme-biophilic select { background: oklch(0.99 0.01 110); border: 1px solid oklch(0.75 0.05 135); border-radius: 1rem 1.4rem 1rem 1.4rem; }
.theme-biophilic input:focus-visible, .theme-biophilic textarea:focus-visible, .theme-biophilic select:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-biophilic kbd { background: oklch(0.93 0.025 115); border: 1px solid oklch(0.72 0.05 135); border-radius: 0.6em 0.9em 0.6em 0.9em; padding: 0.1em 0.5em; font-family: var(--font-mono); font-size: 0.85em; color: oklch(0.35 0.06 150); box-shadow: 0 1px 3px oklch(0.3 0.06 150 / 0.2); }
.theme-biophilic a { color: var(--accent); text-decoration: underline; text-decoration-color: oklch(0.66 0.11 65 / 60%); text-decoration-thickness: 2px; text-underline-offset: 0.22em; transition: text-underline-offset 180ms ease; }
.theme-biophilic a:hover { text-decoration-color: var(--accent-2); text-underline-offset: 0.32em; }
.theme-biophilic ::selection { background: oklch(0.55 0.13 150 / 25%); }
.theme-biophilic ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-biophilic ::-webkit-scrollbar-track { background: oklch(0.92 0.02 110); }
.theme-biophilic ::-webkit-scrollbar-thumb { background: oklch(0.55 0.08 140); border-radius: 9999px; border: 3px solid oklch(0.96 0.018 110); }
.theme-biophilic ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-biophilic .label-caps { color: oklch(0.55 0.1 65); letter-spacing: 0.09em; }
.theme-biophilic .themed-border { border-color: oklch(0.75 0.05 135); }
.theme-biophilic tbody tr:hover td:first-child { box-shadow: inset 3px 0 0 var(--accent-2); }
.theme-biophilic button:hover { border-radius: 2rem 1.25rem 2rem 1.25rem; transition: border-radius 220ms ease; }

/* alt mode: night forest — moonlit canopy, deep greens, warm ember accent */
.theme-biophilic.alt-mode {
  --bg: oklch(0.21 0.035 150);
  --surface: oklch(0.26 0.04 150);
  --surface-2: oklch(0.3 0.045 145);
  --fg: oklch(0.93 0.02 120);
  --fg-muted: oklch(0.72 0.03 130);
  --accent: oklch(0.72 0.12 150);
  --accent-fg: oklch(0.18 0.04 150);
  --accent-2: oklch(0.74 0.12 65);
  --line: oklch(0.4 0.04 145);
  --shadow-1: 0 2px 10px -4px oklch(0.05 0.02 150 / 0.6);
  --shadow-2: 0 10px 30px -12px oklch(0.05 0.02 150 / 0.65);
  --shadow-3: 0 24px 60px -20px oklch(0.05 0.02 150 / 0.7);
  --glow: 0 0 0 4px oklch(0.72 0.12 150 / 0.25);
  background-image:
    radial-gradient(60% 45% at 12% 0%, oklch(0.35 0.06 150 / 0.5), transparent 70%),
    radial-gradient(50% 40% at 92% 12%, oklch(0.35 0.05 90 / 0.4), transparent 70%);
}
.theme-biophilic.alt-mode thead th { color: var(--accent); border-bottom-color: oklch(0.72 0.12 150 / 35%); background: oklch(0.29 0.04 145 / 60%); }
.theme-biophilic.alt-mode td { border-bottom-color: oklch(0.36 0.04 145 / 80%); }
.theme-biophilic.alt-mode tbody tr:hover { background: oklch(0.3 0.045 145 / 70%); }
.theme-biophilic.alt-mode input, .theme-biophilic.alt-mode textarea, .theme-biophilic.alt-mode select { background: oklch(0.24 0.035 150); border-color: oklch(0.42 0.05 145); color: var(--fg); }
.theme-biophilic.alt-mode kbd { background: oklch(0.3 0.04 145); border-color: oklch(0.45 0.05 140); color: oklch(0.88 0.03 120); box-shadow: 0 1px 3px oklch(0 0 0 / 0.4); }
.theme-biophilic.alt-mode a { color: oklch(0.78 0.11 150); text-decoration-color: oklch(0.74 0.12 65 / 55%); }
.theme-biophilic.alt-mode ::selection { background: oklch(0.72 0.12 150 / 30%); }
.theme-biophilic.alt-mode ::-webkit-scrollbar-track { background: oklch(0.24 0.03 148); }
.theme-biophilic.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.45 0.06 145); border-color: oklch(0.21 0.035 150); }
.theme-biophilic.alt-mode .label-caps { color: oklch(0.74 0.12 65); }
.theme-biophilic.alt-mode h2::before { color: var(--accent-2); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
